/* Score model */
function trophyClass(name,r){if(name===r.league)return 'league';if(/World Cup|European Championship|Copa Am[eé]rica|Africa Cup|Asian Cup/i.test(name))return 'international';if(/Champions League|Europa League|Conference League|Copa Libertadores|Club World Cup/i.test(name))return 'continental';return 'domestic'}
function awardValue(name,club=''){if(name==="Ballon d'Or")return POINTS.ballon;if(/^CLUB RECORD/i.test(name))return 0;if(club&&name.startsWith(club+' '))return 120;if(/Supporters|Players’|Players'/i.test(name))return 120;if(/The Best FIFA/i.test(name))return 450;if(/FIFPRO|European Golden Shoe/i.test(name))return 400;if(/Yashin|Kopa|Gerd Müller|Golden Boy|Champions League Player/i.test(name))return 350;if(/Player of the (Year|Season)/i.test(name))return 300;if(/Golden Boot|Golden Glove|Defender of|Midfielder of|Playmaker/i.test(name))return 250;if(/Young Player/i.test(name))return 220;if(/Team of the Season/i.test(name))return 190;return 160}
function scoreParts(r){let domestic=0,league=0,continental=0,international=0;for(const t of r.trophies||[]){const c=trophyClass(t,r);if(c==='league')league+=POINTS.league;else if(c==='continental')continental+=POINTS.continental;else if(c==='international')international+=POINTS.international;else domestic+=POINTS.domestic}const awards=(r.awards||[]).filter(a=>a!=="Ballon d'Or").reduce((s,a)=>s+awardValue(a,r.club),0);return {goals:r.goals*POINTS.goal,assists:r.assists*POINTS.assist,domestic,league,continental,international,awards,ballon:r.ballonDor?POINTS.ballon:0}}

/* Shared points cinematic */
const CATS=[['goals','Goals'],['assists','Assists'],['domestic','Domestic trophies'],['league','League titles'],['continental','Continental trophies'],['international','International trophies'],['awards','Individual awards'],['ballon',"Ballon d'Or"],['total','Season Total']];
function rawFor(r,k){if(k==='goals')return r.goals;if(k==='assists')return r.assists;if(k==='domestic')return (r.trophies||[]).filter(t=>trophyClass(t,r)==='domestic').length;if(k==='league')return (r.trophies||[]).filter(t=>trophyClass(t,r)==='league').length;if(k==='continental')return (r.trophies||[]).filter(t=>trophyClass(t,r)==='continental').length;if(k==='international')return (r.trophies||[]).filter(t=>trophyClass(t,r)==='international').length;if(k==='awards')return (r.awards||[]).filter(a=>a!=="Ballon d'Or"&&awardValue(a,r.club)>0).length;if(k==='ballon')return r.ballonDor?1:0;return r.seasonPoints}
function pointsFor(r,k){return k==='total'?r.seasonPoints:(r.points?.[k]||0)}
function revealGrid(){const rs=room.seasonResults,cols=rs.length;let h=`<div class="mpRevealGrid" style="--players:${cols}"><div class="mpRevealCorner">POINTS</div>`;for(const r of rs)h+=`<div class="mpRevealName" data-player-id="${mpEsc(r.id)}"><b>${mpEsc(r.name)}</b><span>${mpEsc(mpInitials(r.name))}</span></div>`;for(const [k,label] of CATS){h+=`<div class="mpRevealLabel mpRevealTarget ${k==='total'?'total':''}" data-row="${k}">${label}</div>`;for(const r of rs){const raw=rawFor(r,k),pts=pointsFor(r,k);h+=`<div class="mpRevealCell mpRevealTarget ${pts?'earned':''} ${k==='total'?'total':''}" data-row="${k}" data-player-id="${mpEsc(r.id)}"><strong>${k==='total'?pts.toLocaleString():(raw?`${raw} • +${pts.toLocaleString()}`:'—')}</strong><small>${k==='total'?'season points':pts?'points':'no points'}</small></div>`}}return h+'</div>'}
function overlayRoot(cls='mpCinematicOverlay'){let el=$('#mpSharedOverlay');if(el)el.remove();el=document.createElement('div');el.id='mpSharedOverlay';el.className=cls;document.body.appendChild(el);return el}
async function animateNum(el,a,b,d,run,prefix=''){if(!el)return;if(d<=0){el.textContent=prefix+Math.round(b).toLocaleString();return}const t=performance.now();return new Promise(resolve=>{function f(now){if(run!==cinematicRun)return resolve();const q=Math.min(1,(now-t)/d),e=1-Math.pow(1-q,3),v=Math.round(a+(b-a)*e);el.textContent=prefix+v.toLocaleString();if(q<1)requestAnimationFrame(f);else resolve()}requestAnimationFrame(f)})}
async function showBreakdown(){if(!room||room.phase!=='breakdown')return;const key=String(room.revealKey||gateTag());if(breakdownRunKey===key)return;breakdownRunKey=key;const run=++cinematicRun;const wait=Math.max(0,(Number(room.revealAt)||Date.now())-Date.now());if(wait)await sleep(wait);if(run!==cinematicRun||!room||room.phase!=='breakdown'||String(room.revealKey||'')!==key)return;const el=overlayRoot();overlayHeld=false;const rs=room.seasonResults,winner=rs[0];el.innerHTML=`<div class="mpCineShell"><div class="mpCineTop"><div><div class="eyebrow">SEASON ${room.season} • SHARED REVEAL</div><h1>Nobody knows who won yet.</h1><p>Your own season was private. Now everyone sees the points together.</p></div><div class="mpSealedBox"><small>TOP SCORE</small><strong id="mpTopSeal">SEALED</strong></div></div><div class="mpCineCard"><div class="mpCinematicStatus"><span id="mpCineStatus">Preparing the first category…</span><i><b id="mpCineProgress"></b></i></div><div class="mpBreakdownViewport" id="mpBreakdownViewport">${revealGrid()}</div><div class="mpSeasonWinnerReveal" id="mpSeasonWinner"><small>SEASON ${room.season} WINNER</small><b>${mpEsc(winner.name)}</b><span>${winner.seasonPoints.toLocaleString()} points</span></div></div></div>`;
 const view=$('#mpBreakdownViewport'),rows=CATS.map(x=>x[0]);for(let i=0;i<rows.length;i++){if(run!==cinematicRun||room.phase!=='breakdown')return;const key=rows[i],targets=$$(`[data-row="${key}"]`);$('#mpCineStatus').textContent=key==='total'?'The season totals are coming in…':`Revealing ${CATS[i][1].toLowerCase()}…`;$('#mpCineProgress').style.width=`${((i+1)/rows.length)*100}%`;for(let j=0;j<targets.length;j++){targets[j].classList.add('revealed');if(!reduced())await sleep(j===0?80:55)}const first=targets[0];if(view&&first)first.scrollIntoView({behavior:reduced()?'auto':'smooth',block:'center'});await sleep(reduced()?20:(key==='total'?720:430))}
 if(run!==cinematicRun||room.phase!=='breakdown')return;$$(`[data-player-id="${CSS.escape(winner.id)}"]`).forEach(x=>x.classList.add('winnerColumn'));$('#mpTopSeal').textContent=winner.seasonPoints.toLocaleString();$('#mpSeasonWinner').classList.add('show');confetti(90);await sleep(reduced()?40:1350);if(isHost&&room.phase==='breakdown'){room.phase='leaderboard';publish()}}
function rankMovement(oldR,newR){if(newR<oldR)return `<span class="mpMove up">▲${oldR-newR}</span>`;if(newR>oldR)return `<span class="mpMove down">▼${newR-oldR}</span>`;return '<span class="mpMove same">•</span>'}
function leaderboardRows(){const prev=room.previousRanks||{},current={};[...room.players].sort((a,b)=>b.totalPoints-a.totalPoints||a.name.localeCompare(b.name)).forEach((p,i)=>current[p.id]=i+1);const old=[...room.players].sort((a,b)=>(prev[a.id]||99)-(prev[b.id]||99)||a.name.localeCompare(b.name));return old.map(p=>{const before=p.totalPoints-p.lastSeasonPoints;return `<div class="mpScoreRow ${p.id===myId?'you':''}" data-id="${mpEsc(p.id)}" data-old="${prev[p.id]||current[p.id]}" data-new="${current[p.id]}" data-before="${before}" data-after="${p.totalPoints}" data-gain="${p.lastSeasonPoints}"><div class="mpScoreRank"><strong>${prev[p.id]||current[p.id]}</strong><span class="mpMove same">•</span></div><div class="mpScoreIdentity"><b>${mpEsc(p.name)}${p.id===myId?' • You':''}</b><small>${mpEsc(p.careerName||p.club||'Career')} ${p.ended?'• Retired':''}</small></div><div class="mpSeasonGain"><span>+0</span><small>THIS SEASON</small></div><div class="mpScoreTick"><span>${before.toLocaleString()}</span><i>+</i><strong>${before.toLocaleString()}</strong></div></div>`}).join('')}
async function flipRanks(run){const list=$('#mpScoreList'),rows=list?[...list.children]:[];if(!list)return;const first=new Map(rows.map(r=>[r,r.getBoundingClientRect().top]));rows.sort((a,b)=>+a.dataset.new-+b.dataset.new).forEach(r=>list.appendChild(r));const last=new Map(rows.map(r=>[r,r.getBoundingClientRect().top]));for(const r of rows){const dy=(first.get(r)||0)-(last.get(r)||0);r.style.transition='none';r.style.transform=`translateY(${dy}px)`;r.querySelector('.mpScoreRank strong').textContent=r.dataset.new;r.querySelector('.mpMove').outerHTML=rankMovement(+r.dataset.old,+r.dataset.new)}void list.offsetHeight;for(const r of rows){r.style.transition=reduced()?'none':'transform 900ms cubic-bezier(.2,.82,.2,1)';r.style.transform='translateY(0)'}await sleep(reduced()?20:960);if(run!==cinematicRun)return;rows.forEach((r,i)=>{r.style.transition='';r.style.transform='';if(i===0)r.classList.add('leader')})}
async function showLeaderboard(){const run=++cinematicRun,el=overlayRoot(),winner=room.seasonResults[0];overlayHeld=true;el.innerHTML=`<div class="mpCineShell"><div class="mpCineTop"><div><div class="eyebrow">SEASON ${room.season} COMPLETE</div><h1>${mpEsc(winner.name)} won the season.</h1><p>Now the career leaderboard updates.</p></div><div class="mpSealedBox"><small>OVERALL LEADER</small><strong id="mpOverallLeader">•••</strong></div></div><div class="mpCineCard"><div class="eyebrow">OVERALL GAME LEADERBOARD</div><div class="mpLeaderboardStatus" id="mpLeaderStatus">Loading the previous table…</div><div class="mpScoreList" id="mpScoreList">${leaderboardRows()}</div><div class="mpContinueWrap" id="mpContinueWrap"><button class="primary" id="mpContinueCareer">Continue Your Career</button></div></div></div>`;await sleep(reduced()?20:450);$('#mpLeaderStatus').textContent='Adding this season’s points…';const rows=$$('#mpScoreList .mpScoreRow');await Promise.all(rows.map(async(r,i)=>{await sleep(reduced()?0:i*80);const gain=+r.dataset.gain,before=+r.dataset.before,after=+r.dataset.after;await Promise.all([animateNum(r.querySelector('.mpSeasonGain span'),0,gain,reduced()?0:1050,run,'+'),animateNum(r.querySelector('.mpScoreTick strong'),before,after,reduced()?0:1400,run)])}));if(run!==cinematicRun)return;$('#mpLeaderStatus').textContent='Recalculating the order…';await sleep(reduced()?20:380);await flipRanks(run);if(run!==cinematicRun)return;const leader=[...room.players].sort((a,b)=>b.totalPoints-a.totalPoints||a.name.localeCompare(b.name))[0];$('#mpOverallLeader').textContent=mpInitials(leader.name);$('#mpLeaderStatus').textContent=`${leader.name} leads with ${leader.totalPoints.toLocaleString()} points.`;$('#mpContinueWrap').classList.add('show');$('#mpContinueCareer').onclick=()=>{overlayHeld=false;$('#mpSharedOverlay')?.remove();activeTab='journey';renderAll();scrollTo({top:0,behavior:'smooth'})};await sleep(reduced()?20:600);if(isHost&&room.phase==='leaderboard'){if(allEnded()){room.phase='final';publish()}else{room.season++;room.phase='playing';room.seasonResults=[];room.previousRanks=currentRankMap();room.simulationAt=0;room.simulationKey='';room.revealAt=0;room.revealKey='';room.ballonWinnerId=null;room.players.forEach(p=>{p.seasonReady=!!p.ended;p.seasonReadyFor=p.ended?room.season:0;p.seasonDoneFor=0;p.revealReady=false;p.revealReadyFor=0;p.preSeasonEnded=!!p.ended;p.lastSeasonPoints=0});localSeasonReadyFor=0;publish()}}}
async function showFinal(){const run=++cinematicRun,el=overlayRoot('mpFinalOverlay'),ordered=[...room.players].sort((a,b)=>b.totalPoints-a.totalPoints||a.name.localeCompare(b.name)),winner=ordered[0];overlayHeld=false;el.innerHTML=`<div class="mpCineShell"><section class="panel mpFinalHero"><div class="eyebrow">FINAL WHISTLE • EVERY CAREER COMPLETE</div><h1 id="mpFinalName">And the winner is…</h1><div class="mpFinalScore"><span id="mpFinalScore">0</span><small>CAREER POINTS</small></div><div id="mpFinalPodium">${ordered.slice(0,3).map((p,i)=>`<div class="mpPodium ${i===0?'first':''}"><strong>${i+1}</strong><b>${mpEsc(p.name)}</b><small>${p.totalPoints.toLocaleString()} pts • ${mpEsc(p.careerName||'Career')}</small></div>`).join('')}</div></section><div class="mpFinalDetails" id="mpFinalDetails"><section class="mpReplayZone"><div><div class="eyebrow">SAME PARTY. NEW CAREERS.</div><h2>Play again instantly.</h2><p>No new room code. Every connected player gets a fresh Quick Story player and the points reset to zero.</p></div>${isHost?'<button class="primary" id="mpPlayAgain">Play Again With Same Party</button>':'<div class="mpWaiting">Waiting for the host to start another game.</div>'}</section><a class="mpFeedbackLink" href="index.html#reviews-feedback">Finished playing? Leave feedback →</a></div></div>`;await sleep(reduced()?20:650);if(run!==cinematicRun)return;$('#mpFinalName').textContent=`${winner.name} wins Football Legacy`;$('#mpFinalName').classList.add('revealed');confetti(180);await animateNum($('#mpFinalScore'),0,winner.totalPoints,reduced()?0:1700,run);$$('.mpPodium').forEach((p,i)=>setTimeout(()=>p.classList.add('rise'),reduced()?0:i*170));await sleep(reduced()?20:900);$('#mpFinalDetails').classList.add('show');$('#mpPlayAgain')?.addEventListener('click',playAgain)}
function playAgain(){if(!isHost||room.phase!=='final')return;room.gameNo++;room.phase='career_setup';room.season=1;room.seasonResults=[];room.previousRanks={};room.players=room.players.filter(p=>p.connected!==false).map(p=>({...makeRoomPlayer(p.id,p.name)}));resetLocalForNewCareer();preparedGameNo=-1;publish()}

function renderRoom(r){const prev=lastPhase;lastPhase=r.phase;if(r.phase==='lobby'){showLobby();return}hideEntryLobby();if(r.phase==='career_setup'){if(preparedGameNo!==r.gameNo)prepareCareerReveal();return}if(r.phase==='playing'){if(prev==='leaderboard'||prev==='breakdown'||prev==='review'){reviewReady=false;reviewAvailable=false;pendingSeason=null;pendingDelta=0;simulating=false;localScheduledSimulationKey='';localCompletedSimulationKey='';localReviewFinalizedKey='';breakdownRunKey=''}if(state){startGameIfNeeded();renderAll()}if(prev==='leaderboard'&&overlayHeld)return;if(!overlayHeld)$('#mpSharedOverlay')?.remove();return}if(r.phase==='simulating'){if(state){renderAll();scheduleLocalSimulation()}return}if(r.phase==='review'){if(state){renderAll();const me=roomPlayer();if(!me?.preSeasonEnded)finalizeLocalReview(r.ballonWinnerId||null)}return}if(r.phase==='breakdown'){showBreakdown();return}if(r.phase==='leaderboard'){showLeaderboard();return}if(r.phase==='final'){showFinal();return}}
function startGameIfNeeded(){if(!state)return;$('#landing')?.classList.add('hidden');$('#game')?.classList.remove('hidden');$('#settingsBtn')?.classList.remove('hidden');document.body.dataset.mode='story'}
function resetLocalForNewCareer(){try{localStorage.removeItem('footballLegacy_multiplayer_quickstory_v4');localStorage.removeItem('footballLegacy_multiplayer_quickstory_v5');localStorage.removeItem('footballLegacy_multiplayer_quickstory_v6')}catch(e){}state=null;pendingSeason=null;pendingDelta=0;reviewReady=false;reviewAvailable=false;localCareerReady=false;localSeasonReadyFor=0;localScheduledSimulationKey='';localCompletedSimulationKey='';localReviewFinalizedKey='';breakdownRunKey='';honourAdvance=null;overlayHeld=false;$('#mpSharedOverlay')?.remove()}
function careerSeed(){return `MP-${room.code}-${room.gameNo}-${myId}-${room.settings?.position||'ST'}-${room.settings?.rarity||'common'}`}
function createCareerForRoom(seedText){const seed=String(seedText||('MP-'+Date.now())),st={version:4,seed,mode:'story',rng:hash(seed),year:2026,history:[],transfers:[],news:[],pendingOffers:[],pendingStory:null,lastSeason:null,ended:false,createdAt:Date.now(),settings:{motion:true}};const rarity=String(room?.settings?.rarity||'common'),position=POSITIONS.includes(room?.settings?.position)?room.settings.position:'ST',pool=ARCHETYPES.filter(a=>a.rarity===rarity),arch=weighted(st,pool.length?pool:ARCHETYPES.filter(a=>a.rarity==='common')),nationality=pick(st,NATIONALITY_WEIGHTS),age=rint(st,16,18),rating=rint(st,arch.start[0],arch.start[1]),potential=rint(st,Math.max(rating+8,arch.pot[0]),arch.pot[1]),name=randomName(st,nationality),club=chooseStartClub(st,nationality,rating,arch);st.player={name,nationality,position,age,rating,potential,originalPotential:potential,potentialHistory:[{year:2026,value:potential}],peak:rating,archetype:arch.name,rarity:arch.rarity,chancePct:arch.chancePct,growth:arch.growth,volatility:arch.volatility||0,lateBloom:arch.lateBloom||0,historicProfile:arch.historic||0,club,retirementAge:rint(st,35,39),career:{apps:0,goals:0,assists:0,caps:0,intGoals:0,trophies:[],awards:[],records:[]},clubTotals:{},reputation:10,captain:false,clubYears:0,attributes:deriveAttributes(st,rating,position)};st.transfers.push({year:2026,from:null,to:club,fee:0,type:'Academy breakthrough'});st.news.unshift({icon:'🌱',title:'The journey begins',text:`${name} signs a first professional deal with ${club}.`});return st}
function prepareCareerReveal(){if(!room||room.phase!=='career_setup'||localCareerReady||preparedGameNo===room.gameNo)return;resetLocalForNewCareer();preparedGameNo=room.gameNo;state=createCareerForRoom(careerSeed());showCareerReveal()}
function showCareerReveal(){showModal(playerRevealHtml(state));const begin=$('#beginCareerBtn'),reroll=$('#rerollBtn'),back=$('#backModes');reroll?.remove();const actions=begin?.closest('.actions');actions?.insertAdjacentHTML('beforebegin',`<div class="mpLockedBuild"><b>Shared party rules</b><span>${mpEsc(POS_LABEL[room.settings.position]||room.settings.position)} • ${mpEsc(room.settings.rarity.charAt(0).toUpperCase()+room.settings.rarity.slice(1))} rarity</span><small>The host locked these settings for everyone. Your name, club and career path are still your own.</small></div>`);if(begin){begin.textContent='Lock In This Player';begin.onclick=()=>{closeModal();save();startGame();localCareerReady=true;sendHost('career_ready',{gameNo:room.gameNo,careerName:state.player.name,position:state.player.position,rarity:state.player.rarity,club:state.player.club,ovr:state.player.rating});mpToast('Player locked in. Waiting for the whole party.');renderAll()}}if(back){back.textContent='Leave Party';back.onclick=()=>location.href='index.html#play-with-friends'}}
function startParty(){if(!isHost||!room||room.players.length<2)return mpToast('At least two players are needed.');if(room.players.some(p=>p.connected===false))return mpToast('Everyone must be connected before the party can start.');room.phase='career_setup';room.players.forEach(p=>{p.careerReady=false;p.seasonReady=false;p.seasonReadyFor=0;p.seasonDoneFor=0;p.revealReady=false;p.revealReadyFor=0;p.ended=false;p.totalPoints=0;p.lastSeasonPoints=0});publish();prepareCareerReveal();window.flTrack?.('Multiplayer Career Started')}

function entryMarkup(){return `<div class="mpEntry" id="mpEntry"><div class="mpOverlayShell"><div class="mpOverlayBrand"><a href="index.html#modes"><span class="logo">FL</span></a><span class="mpRoomMark">PLAY WITH FRIENDS</span></div><section class="panel mpHeroPanel"><div class="eyebrow">QUICK STORY • TOGETHER</div><h1>Your career.<br>Your friends.<br>One points race.</h1><p>Everyone plays their own full Quick Story career. Transfers, scenarios, trophies, awards and development are personal. Seasons only advance when the whole party is ready.</p></section><div class="mpSetupGrid"><section class="panel mpSetupCard"><div class="eyebrow">START A PARTY</div><h2>Create a room</h2><label>Your nickname<input id="mpHostName" maxlength="18" autocomplete="nickname" placeholder="e.g. Felix"></label><button class="primary" id="mpCreate">Create Room</button></section><section class="panel mpSetupCard"><div class="eyebrow">JOIN A FRIEND</div><h2>Enter a code</h2><label>Your nickname<input id="mpJoinName" maxlength="18" autocomplete="nickname" placeholder="e.g. Sam"></label><label>Room code<input id="mpJoinCode" maxlength="5" autocapitalize="characters" placeholder="ABCDE"></label><button class="mpJoinBtn" id="mpJoin">Join Room</button></section></div><div class="mpFeatureStrip"><span><b>2–6</b> players</span><span><b>Full</b> Quick Story</span><span><b>2</b> ready gates</span></div><section class="panel mpPointPreview"><div class="eyebrow">POINTS PREVIEW</div><h3>Achievements decide the race.</h3><div class="mpPointRules"><div><b>Goal</b><strong>+10</strong></div><div><b>Assist</b><strong>+10</strong></div><div><b>Domestic trophy</b><strong>+250</strong></div><div><b>League title</b><strong>+500</strong></div><div><b>Continental trophy</b><strong>+800</strong></div><div><b>International trophy</b><strong>+1,100</strong></div><div><b>Major awards</b><strong>+120–450</strong></div><div class="gold"><b>Ballon d'Or</b><strong>+1,200</strong></div></div></section></div></div>`}
function showEntry(){document.body.classList.add('mp-entry-open');if(!$('#mpEntry'))document.body.insertAdjacentHTML('beforeend',entryMarkup());$('#mpCreate').onclick=createRoom;$('#mpJoin').onclick=joinRoom}
function hideEntryLobby(){$('#mpEntry')?.remove();$('#mpLobbyOverlay')?.remove();document.body.classList.remove('mp-entry-open')}
function showLobby(){if(!room)return;$('#mpEntry')?.remove();let el=$('#mpLobbyOverlay');if(!el){el=document.createElement('div');el.id='mpLobbyOverlay';el.className='mpLobbyOverlay';document.body.appendChild(el)}const pos=room.settings?.position||'ST',rarity=room.settings?.rarity||'common',posOptions=POSITIONS.map(x=>`<option value="${x}" ${x===pos?'selected':''}>${mpEsc(POS_LABEL[x]||x)}</option>`).join(''),rarityOptions=['common','uncommon','rare','epic','legendary','mythic'].map(x=>`<option value="${x}" ${x===rarity?'selected':''}>${x.charAt(0).toUpperCase()+x.slice(1)}</option>`).join('');el.innerHTML=`<div class="mpOverlayShell"><div class="mpOverlayBrand"><a href="index.html#modes"><span class="logo">FL</span></a><span class="mpRoomMark">WAITING ROOM</span></div><div class="mpLobbyHead"><div><div class="eyebrow">PLAY WITH FRIENDS</div><h1>${room.players.length} of ${MAX_PLAYERS} players</h1></div><button class="mpCode" id="mpCopyCode"><small>TAP TO COPY</small><strong>${room.code}</strong></button></div><section class="panel mpLobbyPanel"><div class="eyebrow">PARTY</div><div class="mpPlayers">${room.players.map(p=>`<div class="mpPlayerTile"><div class="mpAvatar">${mpEsc(mpInitials(p.name))}</div><div><b>${mpEsc(p.name)}${p.id===myId?' • You':''}</b><small>${p.id===room.players[0].id?'HOST • ':''}${p.connected===false?'DISCONNECTED':'READY'}</small></div><i class="mpReadyDot ${p.connected!==false?'on':''}"></i></div>`).join('')}</div>${isHost?`<div class="mpSharedSetup"><div><div class="eyebrow">HOST-LOCKED PLAYER RULES</div><h3>Same rarity. Same position. Different careers.</h3><p>These two settings apply to every player in the room. Once the game starts they cannot be changed.</p></div><div class="mpSharedSetupGrid"><label>Position<select id="mpSharedPosition">${posOptions}</select></label><label>Rarity<select id="mpSharedRarity">${rarityOptions}</select></label></div></div><button class="primary" id="mpStart" ${room.players.length<2||room.players.some(p=>p.connected===false)?'disabled':''}>Start Quick Story Careers</button>`:`<div class="mpSharedSetup locked"><div><div class="eyebrow">HOST-LOCKED PLAYER RULES</div><h3>${mpEsc(POS_LABEL[pos]||pos)} • ${mpEsc(rarity.charAt(0).toUpperCase()+rarity.slice(1))}</h3><p>The host chooses these settings for the whole party. Your actual player, club, transfers and career path will still be unique.</p></div></div><div class="mpWaiting">Waiting for the host to start the shared Quick Story careers.</div>`}</section></div>`;$('#mpCopyCode').onclick=()=>navigator.clipboard?.writeText(room.code).then(()=>mpToast('Room code copied.')).catch(()=>mpToast('Room code: '+room.code));if(isHost){$('#mpSharedPosition')?.addEventListener('change',e=>{if(room.phase!=='lobby')return;room.settings.position=POSITIONS.includes(e.target.value)?e.target.value:'ST';publish()});$('#mpSharedRarity')?.addEventListener('change',e=>{if(room.phase!=='lobby')return;const allowed=['common','uncommon','rare','epic','legendary','mythic'];room.settings.rarity=allowed.includes(e.target.value)?e.target.value:'common';publish()})}$('#mpStart')?.addEventListener('click',startParty)}

function init(){showEntry();const modal=$('#modal');modal?.addEventListener('click',e=>{if(e.target.closest?.('[data-new]')&&room){e.preventDefault();e.stopImmediatePropagation();mpToast('Use Play Again With Same Party after the final result.') }},true);document.addEventListener('click',e=>{const b=e.target.closest?.('[data-mp-honour-continue],button[id^="mpV8-"]');if(!b||typeof honourAdvance!=='function')return;e.preventDefault();e.stopPropagation();const fn=honourAdvance;honourAdvance=null;fn()},true)}
init();
function qaRun(){const fail=[],careers=[];try{const keepRoom=room;room={code:'QA-RULES',gameNo:3,phase:'career_setup',season:4,settings:{position:'CM',rarity:'rare'},players:[],seasonResults:[],previousRanks:{}};for(let i=0;i<6;i++){const st=createCareerForRoom(`MP-QA-${i}`),moves=[];if(st.player.position!=='CM')fail.push('shared position not enforced');if(st.player.rarity!=='rare')fail.push('shared rarity not enforced');for(let y=0;y<12&&!st.ended;y++){if(st.pendingOffers.length){const best=st.pendingOffers.map((o,j)=>({o,j})).sort((a,b)=>b.o.fit-a.o.fit)[0];if(best?.o.fit>=62){moves.push(y+1);acceptOffer(st,best.j)}else stayPut(st)}if(st.pendingStory){storyModifier(st,(i+y)%3);st.storyDecisionReady=null}simulateSeason(st,null)}careers.push({name:st.player.name,start:st.transfers[0]?.to,club:st.player.club,ovr:st.player.rating,moves,seasons:st.history.length,position:st.player.position,rarity:st.player.rarity})}for(const pos of POSITIONS)for(const rarity of ['common','uncommon','rare','epic','legendary','mythic']){room.settings={position:pos,rarity};const st=createCareerForRoom(`RULE-${pos}-${rarity}`);if(st.player.position!==pos)fail.push(`position rule failed: ${pos}`);if(st.player.rarity!==rarity)fail.push(`rarity rule failed: ${rarity}`)}room.settings={position:'CM',rarity:'rare'};if(new Set(careers.map(x=>x.name+'|'+x.start)).size<4)fail.push('careers are not sufficiently distinct');if(new Set(careers.map(x=>x.moves.join(','))).size<2)fail.push('transfer timing did not diverge');room={code:'QA-GATE',gameNo:7,phase:'playing',season:5,settings:{position:'ST',rarity:'common'},players:[makeRoomPlayer('a','A'),makeRoomPlayer('b','B')],seasonResults:[],previousRanks:{}};room.players.forEach(p=>{p.careerReady=true});room.players[0].seasonReadyFor=5;room.players[0].seasonReady=true;if(allSeasonReady())fail.push('gate opened before everyone was ready');room.players[1].connected=false;room.players[1].seasonReadyFor=5;room.players[1].seasonReady=true;if(allSeasonReady())fail.push('disconnected player was silently ignored by gate');room.players[1].connected=true;if(!allSeasonReady())fail.push('gate did not open when both players were ready for exact season');room.players[1].seasonReadyFor=4;if(allSeasonReady())fail.push('stale ready from previous season opened gate');isHost=true;room.players[1].seasonReadyFor=0;room.players[0].seasonReadyFor=0;handleHostMessage({peer:'a'},{type:'season_ready',gameNo:7,season:5},true);if(room.phase!=='playing')fail.push('host advanced after only one ready message');handleHostMessage({peer:'b'},{type:'season_ready',gameNo:7,season:4},false);if(room.phase!=='playing')fail.push('stale season ready advanced host');handleHostMessage({peer:'b'},{type:'season_ready',gameNo:7,season:5},false);if(room.phase!=='simulating')fail.push(`exact two-player ready barrier did not open: phase=${room.phase}`);isHost=false;room.phase='review';room.season=5;room.players.forEach(p=>{p.preSeasonEnded=false;p.revealReady=false;p.revealReadyFor=0;p.connected=true});room.players[0].revealReadyFor=5;if(allRevealReady())fail.push('points gate opened before everyone was ready');room.players[1].connected=false;room.players[1].revealReadyFor=5;if(allRevealReady())fail.push('disconnected player was ignored by points gate');room.players[1].connected=true;if(!allRevealReady())fail.push('points gate did not open for exact season');room.players[1].revealReadyFor=4;if(allRevealReady())fail.push('stale reveal-ready opened points gate');const sample={goals:4,assists:3,league:'Premier League',trophies:['Premier League','FA Cup','Champions League','World Cup'],awards:["Ballon d'Or",'Premier League Player of the Season'],ballonDor:true},parts=scoreParts(sample),total=Object.values(parts).reduce((a,b)=>a+b,0);if(parts.goals!==40||parts.assists!==30||parts.league!==500||parts.domestic!==250||parts.continental!==800||parts.international!==1100||parts.awards!==300||parts.ballon!==1200)fail.push('point categories mismatch');if(total!==4220)fail.push(`point total mismatch: ${total}`);room={code:'QA-BALLON',gameNo:1,season:1};const candidates=Array.from({length:6},(_,i)=>({id:`p${i}`,participated:true,ballonEligible:true,ballonScore:100-i,ballonProb:1}));for(let season=1;season<=100;season++){room.season=season;const winner=chooseBallonWinner(candidates);if(winner&&!candidates.some(x=>x.id===winner))fail.push('Ballon winner not in candidate set')}room=keepRoom}catch(e){fail.push(e.stack||String(e))}return {ok:!fail.length,fail,careers}};

function protocolQaRun(){
 const fail=[],keep={room,isHost,myId,state,localSeasonReadyFor,localScheduledSimulationKey,localCompletedSimulationKey,localReviewFinalizedKey,breakdownRunKey};
 try{
  isHost=true;myId='host';state=null;localSeasonReadyFor=0;localScheduledSimulationKey='';localCompletedSimulationKey='';localReviewFinalizedKey='';breakdownRunKey='';
  room={code:'SYNC6',gameNo:2,phase:'playing',season:3,settings:{position:'ST',rarity:'rare'},players:[makeRoomPlayer('host','Host'),makeRoomPlayer('friend','Friend')],seasonResults:[],previousRanks:{}};
  room.players.forEach(p=>{p.careerReady=true;p.connected=true;p.club='Test FC';p.ovr=70});
  handleHostMessage({peer:'host'},{type:'season_ready',gameNo:2,season:3},true);
  if(room.phase!=='playing')fail.push('one player unlocked simulation');
  handleHostMessage({peer:'friend'},{type:'season_ready',gameNo:2,season:2},false);
  if(room.phase!=='playing')fail.push('stale season ready unlocked simulation');
  handleHostMessage({peer:'friend'},{type:'season_ready',gameNo:2,season:3},false);
  if(room.phase!=='simulating')fail.push('all ready did not enter synchronized simulation');
  if(!(room.simulationAt>Date.now()))fail.push('synchronized simulation has no future start time');
  if(room.seasonResults.length)fail.push('a season simulated before the synchronized start/result messages');
  const base={careerName:'Player',position:'ST',club:'Test FC',nextClub:'Test FC',ovr:71,potential:80,ended:false,participated:true,apps:30,goals:10,assists:5,avg:7.1,grade:'B',league:'Test League',leaguePosition:4,trophies:[],awards:[],ballonEligible:false,ballonProb:0,ballonScore:0};
  handleHostMessage({peer:'host'},{type:'season_done',gameNo:2,season:3,result:base},true);
  if(room.phase!=='simulating')fail.push('review opened before every player finished simulation');
  handleHostMessage({peer:'friend'},{type:'season_done',gameNo:2,season:3,result:{...base,goals:7}},false);
  if(room.phase!=='review')fail.push('all completed seasons did not open private review stage');
  handleHostMessage({peer:'host'},{type:'reveal_ready',gameNo:2,season:3},true);
  if(room.phase!=='review')fail.push('one player unlocked points reveal');
  handleHostMessage({peer:'friend'},{type:'reveal_ready',gameNo:2,season:2},false);
  if(room.phase!=='review')fail.push('stale reveal ready unlocked points reveal');
  handleHostMessage({peer:'friend'},{type:'reveal_ready',gameNo:2,season:3},false);
  if(room.phase!=='breakdown')fail.push('all review-ready players did not unlock points reveal');
  if(!(room.revealAt>Date.now()))fail.push('points reveal has no synchronized future start time');
  room.phase='simulating';room.season=4;state=createCareerForRoom('SCENARIO-TIMING-QA');state.pendingStory=null;state.mpScenarioPreparedFor=null;const rngBeforeBlocked=state.rng;if(maybeStory(state)!==null)fail.push('scenario appeared during simulation/review window');if(state.rng!==rngBeforeBlocked)fail.push('blocked scenario changed RNG outside season start');room.phase='playing';const firstScenario=maybeStory(state),preparedTag=state.mpScenarioPreparedFor,rngAfterFirst=state.rng;maybeStory(state);if(preparedTag!==gateTag())fail.push('scenario was not tagged to the exact season start');if(state.rng!==rngAfterFirst)fail.push('scenario rolled more than once in one season');room.phase='review';if(maybeStory(state)!==null)fail.push('scenario appeared during private review');
  room.phase='playing';room.season=4;room.players.forEach(p=>{p.seasonReadyFor=0;p.seasonReady=false});state={pendingOffers:[{club:'X'}],pendingStory:null,ended:false};playSeasonUI();if(room.players[0].seasonReadyFor===4)fail.push('transfer offer did not block season ready');
  state={pendingOffers:[],pendingStory:{title:'Decision'},ended:false};playSeasonUI();if(room.players[0].seasonReadyFor===4)fail.push('scenario did not block season ready');
 }catch(e){fail.push(e.stack||String(e))}
 room=keep.room;isHost=keep.isHost;myId=keep.myId;state=keep.state;localSeasonReadyFor=keep.localSeasonReadyFor;localScheduledSimulationKey=keep.localScheduledSimulationKey;localCompletedSimulationKey=keep.localCompletedSimulationKey;localReviewFinalizedKey=keep.localReviewFinalizedKey;breakdownRunKey=keep.breakdownRunKey;
 return {ok:!fail.length,fail};
}

window.FL_MULTIPLAYER_QUICK_V8={getRoom:()=>room,points:POINTS,scoreParts,awardValue,qaRun,protocolQaRun,__test:{createRoom,joinRoom,handleHostMessage,handleClientMessage,cleanupPeerSession,mpPeerId}};
